static void search(int candidates[],int size,int start,int target,int path[],int depth,int result[][16],int lengths[],int *count){int i;int j;if(target==0){for(j=0;j<depth;j=j+1)result[*count][j]=path[j];lengths[*count]=depth;*count=*count+1;return;}for(i=start;i<size;i=i+1){if(candidates[i]<=target){path[depth]=candidates[i];search(candidates,size,i,target-candidates[i],path,depth+1,result,lengths,count);}}}
int combination_sum(int candidates[],int size,int target,int result[][16],int lengths[]){int path[16];int count;count=0;search(candidates,size,0,target,path,0,result,lengths,&count);return count;}
int main(void){int a[4]={2,3,6,7};int b[3]={2,3,5};int r[32][16];int l[32];int c;c=combination_sum(a,4,7,r,l);if(c!=2)return 1;if(l[0]!=3||r[0][0]!=2||r[0][1]!=2||r[0][2]!=3)return 2;if(l[1]!=1||r[1][0]!=7)return 3;c=combination_sum(b,3,8,r,l);if(c!=3)return 4;return 42;}
